'use client'
import { useState } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { api } from '@/lib/api'

export default function MetaTxForm() {
  const [target, setTarget] = useState('0x145863Eb42Cf62847A6Ca784e6416C1682b1b2Ae')
  const [status, setStatus] = useState('')

  const execute = async () => {
    setStatus('⛽ Executing meta-tx...')
    
    // TODO: Real wallet integration
    try {
      const res = await api.executeMetaTx({
        request: {
          from: '0xYourAgentWallet',
          to: target,
          value: '0',
          gas: '200000',
          nonce: '0',
          deadline: Math.floor(Date.now() / 1000 + 3600).toString(),
          data: '0x'
        },
        signature: '0x...', // TODO: Sign with wagmi
        priority: 'normal'
      })
      
      setStatus(`✅ Tx: ${res.txHash.slice(0, 12)}...`)
    } catch (e: any) {
      setStatus(`❌ ${e.message}`)
    }
  }

  return (
    <div className="glass p-8 rounded-3xl border border-green-500/30 neon-green">
      <h3 className="text-2xl font-black gradient-text mb-6">Execute Meta-Tx</h3>
      
      <div className="space-y-4 mb-8">
        <div>
          <label className="block text-lg font-bold mb-2 text-green-400">Target Contract</label>
          <Input
            value={target}
            onChange={(e) => setTarget(e.target.value)}
            placeholder="0x... VVS Router, etc"
            className="text-xl bg-black/50 border-green-500/50"
          />
        </div>
        
        <div className="grid grid-cols-2 gap-4">
          <Button 
            className="h-16 bg-gradient-to-r from-orange-500 to-yellow-500 font-black text-xl hover:from-orange-600"
            onClick={() => alert('Faucet clicked')}
          >
            💧 Get TestUSDC
          </Button>
          <Button 
            className="h-16 bg-gradient-to-r from-green-500 to-blue-500 font-black text-xl hover:from-green-600 neon-green"
            onClick={execute}
          >
            ⛽ Execute Tx
          </Button>
        </div>
      </div>
      
      {status && (
        <div className="p-6 rounded-2xl bg-black/50 border-2 border-green-500/50 text-center font-mono text-lg">
          {status}
        </div>
      )}
    </div>
  )
}
